// Title: Land of the Rising Dots
// Author: Claude, ItsWesSmithYo
// Project: OneManShYo

// Function to rotate a point around an origin
mat2 rotate(float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return mat2(c, -s, s, c);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates to [-1, 1] and adjust for aspect ratio
    vec2 uv = fragCoord / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    // Animation variables
    float time = iTime;
    float loopTime = 5.0; // Loop every 5 seconds
    float t = mod(time, loopTime) / loopTime;

    // Center of the face
    vec2 center = vec2(0.0);

    // Scale of the smiley face
    float scale = 0.3;

    // Random rotations for parts
    float faceRotation = t * 2.0 * 3.14159; // Rotates once per loop
    float leftEyeRotation = t * 6.28; // Faster rotation
    float rightEyeRotation = t * 4.0 * 3.14159; // Medium speed
    float mouthRotation = t * 3.0 * 3.14159; // Slower rotation

    // Rotate UV for face rotation
    uv -= center;
    uv = rotate(faceRotation) * uv;
    uv += center;

    // Drawing the face circle
    float face = length(uv - center) - scale;

    // Left eye (circle)
    vec2 leftEyePos = vec2(-scale * 0.4, scale * 0.4);
    vec2 leftEyeUV = uv - leftEyePos;
    leftEyeUV = rotate(leftEyeRotation) * leftEyeUV; // Rotate the left eye
    float leftEye = length(leftEyeUV) - scale * 0.1;

    // Right eye (X)
    vec2 rightEyePos = vec2(scale * 0.4, scale * 0.4);
    vec2 rightEyeUV = uv - rightEyePos;
    rightEyeUV = rotate(rightEyeRotation) * rightEyeUV; // Rotate the right eye
    float x1 = abs(rightEyeUV.y - rightEyeUV.x) - 0.02;
    float x2 = abs(rightEyeUV.y + rightEyeUV.x) - 0.02;
    float rightEye = min(x1, x2);

    // Mouth (slash)
    vec2 mouthPos = vec2(0.0, -scale * 0.4);
    vec2 mouthUV = uv - mouthPos;
    mouthUV = rotate(mouthRotation) * mouthUV; // Rotate the mouth
    float mouth = abs(mouthUV.y - 0.5 * mouthUV.x) - 0.02;

    // Combine all shapes
    float faceShape = smoothstep(0.02, 0.01, face);
    float leftEyeShape = smoothstep(0.01, 0.005, leftEye);
    float rightEyeShape = smoothstep(0.01, 0.005, rightEye);
    float mouthShape = smoothstep(0.01, 0.005, mouth);

    // Combine colors
    vec3 col = vec3(1.0); // White background
    col = mix(col, vec3(0.0), faceShape);  // Face outline
    col = mix(col, vec3(0.0), leftEyeShape);  // Left eye
    col = mix(col, vec3(0.0), rightEyeShape);  // Right eye
    col = mix(col, vec3(0.0), mouthShape);  // Mouth

    // Output the final color
    fragColor = vec4(col, 1.0);
}
